<?php
require_once __DIR__.'/../config/app.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: claims.php');exit();}$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if(!in_array($action,['approve','reject'],true)){set_flash('error','Invalid claim action.');header('Location: claims.php');exit();}$s=mysqli_prepare($conn,"SELECT claims.*,items.user_id reporter_id FROM claims INNER JOIN items ON items.id=claims.item_id WHERE claims.id=? AND claims.status='pending'");mysqli_stmt_bind_param($s,'i',$id);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);if(mysqli_num_rows($r)!==1){set_flash('error','Pending claim not found.');header('Location: claims.php');exit();}$c=mysqli_fetch_assoc($r);$item=(int)$c['item_id'];$claimant=(int)$c['user_id'];$reporter=(int)$c['reporter_id'];if($action==='approve'){mysqli_begin_transaction($conn);try{$u=mysqli_prepare($conn,"UPDATE claims SET status='approved' WHERE id=?");mysqli_stmt_bind_param($u,'i',$id);mysqli_stmt_execute($u);$o=mysqli_prepare($conn,"UPDATE claims SET status='rejected' WHERE item_id=? AND id!=? AND status='pending'");mysqli_stmt_bind_param($o,'ii',$item,$id);mysqli_stmt_execute($o);$it=mysqli_prepare($conn,"UPDATE items SET status='returned' WHERE id=?");mysqli_stmt_bind_param($it,'i',$item);mysqli_stmt_execute($it);$m='Your claim was approved. The item has been marked as returned.';$n=mysqli_prepare($conn,'INSERT INTO notifications(user_id,message) VALUES(?,?)');mysqli_stmt_bind_param($n,'is',$claimant,$m);mysqli_stmt_execute($n);$rm='A claim for one of your found items was approved. The item is now marked as returned.';$n2=mysqli_prepare($conn,'INSERT INTO notifications(user_id,message) VALUES(?,?)');mysqli_stmt_bind_param($n2,'is',$reporter,$rm);mysqli_stmt_execute($n2);mysqli_commit($conn);set_flash('success','Claim approved and item marked as returned.');}catch(Throwable $e){mysqli_rollback($conn);set_flash('error','Could not approve the claim.');}}else{$u=mysqli_prepare($conn,"UPDATE claims SET status='rejected' WHERE id=?");mysqli_stmt_bind_param($u,'i',$id);mysqli_stmt_execute($u);$m='Your claim request was rejected.';$n=mysqli_prepare($conn,'INSERT INTO notifications(user_id,message) VALUES(?,?)');mysqli_stmt_bind_param($n,'is',$claimant,$m);mysqli_stmt_execute($n);set_flash('success','Claim rejected.');}header('Location: claims.php');exit();
?>